import{_ as a,o as n,c as e,a1 as t}from"./chunks/framework.Dvq7PH7Q.js";const g=JSON.parse('{"title":"我是怎么把这个博客搭起来的","description":"借助 AI 智能体搭建个人博客的全过程——从选型、写码到部署上线，以及让它帮我整理每天的工作。","frontmatter":{"title":"我是怎么把这个博客搭起来的","date":"2026-08-19T00:00:00.000Z","tags":["VitePress","博客","折腾"],"description":"借助 AI 智能体搭建个人博客的全过程——从选型、写码到部署上线，以及让它帮我整理每天的工作。"},"headers":[],"relativePath":"posts/how-i-built-this-blog.md","filePath":"posts/how-i-built-this-blog.md","lastUpdated":1787215089000}'),o={name:"posts/how-i-built-this-blog.md"};function i(l,s,p,r,d,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="我是怎么把这个博客搭起来的" tabindex="-1">我是怎么把这个博客搭起来的 <a class="header-anchor" href="#我是怎么把这个博客搭起来的" aria-label="Permalink to &quot;我是怎么把这个博客搭起来的&quot;">​</a></h1><p>一直想有个地方安放零散的记录和想法，拖了很久。这次终于动手——而且整个过程是<strong>借助 AI 智能体</strong>完成的，从选型到上线只花了大半天，值得写下来。</p><h2 id="为什么选-vitepress" tabindex="-1">为什么选 VitePress <a class="header-anchor" href="#为什么选-vitepress" aria-label="Permalink to &quot;为什么选 VitePress&quot;">​</a></h2><p>先让智能体帮我列了几个候选对比：</p><ul><li><strong>Hexo</strong>：老牌博客框架，主题多，但 Node 依赖链长，改样式要碰 EJS。</li><li><strong>Hugo</strong>：快，但 Go 模板不是我的主场，主题定制成本高。</li><li><strong>VitePress</strong>：基于 Vite，写 Markdown 就是写博客，零运行时负担，还能完全用 Vue 组件定制——最终选了它。</li></ul><p>VitePress 官方定位是文档站，但拿来做个人博客非常合适：原生 Markdown 渲染、代码高亮、暗色模式都是现成的，需要的东西自己写几个 Vue 组件就能补上。</p><h2 id="借助智能体搭建" tabindex="-1">借助智能体搭建 <a class="header-anchor" href="#借助智能体搭建" aria-label="Permalink to &quot;借助智能体搭建&quot;">​</a></h2><p>整个搭建过程基本是<strong>我说需求，智能体动手</strong>：</p><ul><li>我只需要描述想要什么（文章列表、标签分类、关于页、日记归档……），智能体直接生成配置文件、主题组件和页面；</li><li>遇到问题直接丢给它排查（主页空白、frontmatter 取不到、构建报错、推不上去……），它分析根因后给出修复；</li><li>最后部署也是它一手包办：建仓库、推分支、开 GitHub Pages、验证上线。</li></ul><p>我做的，只是<strong>想清楚自己想要什么、以及确认它做出来的东西对不对</strong>。这种协作方式体验下来最大的感受是：<strong>把&quot;怎么做&quot;交给 AI，把&quot;做什么、好不好&quot;留给自己</strong>。</p><h2 id="让智能体整理每天的工作" tabindex="-1">让智能体整理每天的工作 <a class="header-anchor" href="#让智能体整理每天的工作" aria-label="Permalink to &quot;让智能体整理每天的工作&quot;">​</a></h2><p>博客搭好之后，我给它加了一个新任务：<strong>每天晚上让它帮我整理当天的工作，做好记录</strong>。</p><ul><li>白天我做了什么、卡在哪里、有哪些想法，随时丢给它；</li><li>它会把散乱的信息整理成有条理的记录，存进博客的日记里；</li><li>这样一段时间后回看，每天的轨迹都清清楚楚，不用自己费力回忆。</li></ul><p>这也是这个博客「日记」板块的由来——不只是情绪流水账，更是<strong>工作与生活的整理归档</strong>。</p><h2 id="站点结构" tabindex="-1">站点结构 <a class="header-anchor" href="#站点结构" aria-label="Permalink to &quot;站点结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>H:\\blog</span></span>
<span class="line"><span>├── index.md              # 主页（hero + 特性卡 + 最新文章）</span></span>
<span class="line"><span>├── posts.md              # 全部文章</span></span>
<span class="line"><span>├── tags.md               # 标签分类</span></span>
<span class="line"><span>├── diary.md              # 日记（按月归档）</span></span>
<span class="line"><span>├── about.md              # 关于</span></span>
<span class="line"><span>├── posts/                # 文章都在这里，一篇一个 .md</span></span>
<span class="line"><span>│   ├── how-i-built-this-blog.md</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>├── public/               # 静态资源（头像等）</span></span>
<span class="line"><span>└── .vitepress/</span></span>
<span class="line"><span>    ├── config.mjs        # 站点配置</span></span>
<span class="line"><span>    └── theme/</span></span>
<span class="line"><span>        ├── index.js      # 主题入口（注册全局组件）</span></span>
<span class="line"><span>        ├── style.css     # 全局样式</span></span>
<span class="line"><span>        └── components/   # 自定义组件</span></span></code></pre></div><p>写新文章就是往 <code>posts/</code> 丢一个 <code>.md</code>，头部写好 <code>title / date / tags / description</code>，首页和标签页会自动聚合——这也是选 VitePress 的最大理由：<strong>内容即文件，无需数据库</strong>。</p><h2 id="部署-github-pages" tabindex="-1">部署：GitHub Pages <a class="header-anchor" href="#部署-github-pages" aria-label="Permalink to &quot;部署：GitHub Pages&quot;">​</a></h2><p>部署方案用了 <strong>gh-pages 分支</strong>（源码在 <code>main</code>，构建产物在 <code>gh-pages</code>），而不是 GitHub Actions：</p><ul><li>Actions 工作流文件需要 token 有 <code>workflow</code> 权限，我的授权 token 没有，推送会被 GitHub 直接拒绝；</li><li>改成分支部署后，每次更新就是：本地构建 → 把 <code>dist</code> 推到 <code>gh-pages</code> → Pages 自动重新发布。</li></ul><h2 id="踩过的坑" tabindex="-1">踩过的坑 <a class="header-anchor" href="#踩过的坑" aria-label="Permalink to &quot;踩过的坑&quot;">​</a></h2><ol><li><strong>组件没注册，主页空白</strong>：<code>PostList</code> / <code>TagList</code> 写好了但没在主题里注册成全局组件，结果主页只剩两行字——第一版上线后才发现，赶紧补上 <code>app.component(...)</code>。</li><li><strong>取不到 frontmatter</strong>：VitePress 1.x 不给 Markdown 模块导出 <code>frontmatter</code>，列表显示成了文件名。最后用 <code>?raw</code> 读原文 + 自己写了个极简 YAML 解析器。</li><li><strong>本地构建报 exit 1</strong>：Windows 上 H: 盘没有回收站，构建末尾清理临时目录时删除失败。禁用安全删除拦截后构建就干净了。</li><li><strong>上传网络不稳</strong>：推送 <code>gh-pages</code> 时连接反复被重置，靠&quot;重试 + 校验远程 SHA&quot;的循环才推上去。</li></ol><h2 id="之后想做的" tabindex="-1">之后想做的 <a class="header-anchor" href="#之后想做的" aria-label="Permalink to &quot;之后想做的&quot;">​</a></h2><ul><li>写更多技术笔记（前端为主）；</li><li>坚持每天让智能体整理工作记录，把日记板块养起来；</li><li>也许加个留言板（先用评论区服务）。</li></ul><p>这里会持续更新，欢迎常来。</p>`,25)])])}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
